import{_ as i,C as s,c as l,o as c,ah as n,j as e,G as a,a as r}from"./chunks/framework.C2OYgiIb.js";const w=JSON.parse('{"title":"Work Centers","description":"","frontmatter":{},"headers":[],"relativePath":"master/manufacturing/configurations/work-centers.md","filePath":"master/manufacturing/configurations/work-centers.md","lastUpdated":1779101762000}'),u={name:"master/manufacturing/configurations/work-centers.md"};function g(m,t,p,d,h,f){const o=s("ImagePopup");return c(),l("div",null,[t[9]||(t[9]=n('<h1 id="work-centers" tabindex="-1">Work Centers <a class="header-anchor" href="#work-centers" aria-label="Permalink to &quot;Work Centers&quot;">​</a></h1><p><strong>Work Centers</strong> are the physical (or virtual) production resources where manufacturing operations are performed — for example <em>Assembly Line 1</em>, <em>CNC Machine</em>, <em>Packaging Station</em>, or <em>Quality Check Booth</em>.<br> They define <strong>capacity</strong>, <strong>working hours</strong>, <strong>costs</strong>, and <strong>efficiency</strong> for every operation that runs through them, allowing the system to schedule work orders realistically and report on shop-floor performance.</p><p><strong>Use Case:</strong><br> Set up a Work Center for every distinct machine, line, or area that performs production steps. Once configured, <a href="./../operations/work-orders.html">Work Orders</a> are routed to the right station with the correct duration, cost, and capacity.</p><blockquote><p><strong>In simple words:</strong> A Work Center is a <em>place where work happens</em> — a machine, a table, or a team. <a href="./operations.html">Operations</a> are assigned to Work Centers so the system knows where each production step is carried out.</p></blockquote><blockquote><p>Work Centers are only available when <strong>Work Orders</strong> is enabled in <a href="./../settings.html">Manufacturing Settings</a>.</p></blockquote><h2 id="steps-to-create-a-new-work-center" tabindex="-1">Steps to Create a New Work Center <a class="header-anchor" href="#steps-to-create-a-new-work-center" aria-label="Permalink to &quot;Steps to Create a New Work Center&quot;">​</a></h2>',6)),e("ol",null,[e("li",null,[t[0]||(t[0]=e("p",null,[r("Navigate to "),e("strong",null,[e("code",null,"Manufacturing → Configurations → Work Centers")]),r(" as shown below:")],-1)),a(o,{src:"/images1/manufacturing/work_center_navigation.png",alt:"Work Centers Navigation"})]),e("li",null,[t[1]||(t[1]=n('<p>Fill in the following details:</p><h4 id="general-section" tabindex="-1">General Section <a class="header-anchor" href="#general-section" aria-label="Permalink to &quot;General Section&quot;">​</a></h4><ul><li><strong><em>Name:</em></strong> The display name of the work center (e.g. <code>Assembly Line 1</code>). This is shown wherever the work center is referenced.</li><li><strong><em>Code:</em></strong> A short identifier used internally and on reports (e.g. <code>AL1</code>).</li><li><strong><em>Tag:</em></strong> Add one or more tags to group similar work centers (e.g. <em>Heavy Machinery</em>, <em>Manual</em>, <em>Automated</em>).</li><li><strong><em>Alternative Work Centers:</em></strong> Select other work centers that can perform the same job. When the primary work center is busy, the system can suggest these alternatives so production isn&#39;t blocked.</li><li><strong><em>Company:</em></strong> Choose the company that owns this work center (useful in multi-company setups).</li><li><strong><em>Working Hours:</em></strong> Select the schedule (calendar) that defines when this work center is available (e.g. <em>Standard 40h/week</em>, <em>Two Shifts</em>).</li></ul>',3)),a(o,{src:"/images1/manufacturing/work_center_general_section.png",alt:"Work Center General Section"}),t[2]||(t[2]=n('<h4 id="production-information" tabindex="-1">Production Information <a class="header-anchor" href="#production-information" aria-label="Permalink to &quot;Production Information&quot;">​</a></h4><ul><li><strong><em>Default Capacity:</em></strong> The number of product units this work center can process <strong>simultaneously</strong> in one run. Example: an oven that bakes 24 units in one batch has a capacity of 24.</li><li><strong><em>Time Efficiency (%):</em></strong> Productivity factor of the work center. A value below 100% lengthens the planned duration to account for slowdowns; above 100% shortens it. Example: 80% means a 60-minute task is actually scheduled for 75 minutes.</li><li><strong><em>OEE Target (%):</em></strong> The target <strong>Overall Equipment Effectiveness</strong> for this work center. Used as a benchmark in reports to compare planned vs. actual performance.</li></ul><h4 id="costing-information" tabindex="-1">Costing Information <a class="header-anchor" href="#costing-information" aria-label="Permalink to &quot;Costing Information&quot;">​</a></h4><ul><li><strong><em>Cost per Hour:</em></strong> The operating cost charged for every hour the work center is in use (energy, labor, depreciation). Used to compute the production cost of each manufacturing order.</li><li><strong><em>Setup Time (minutes):</em></strong> Time required to prepare the work center <strong>before</strong> an operation starts (e.g. machine warm-up, tool change).</li><li><strong><em>Cleanup Time (minutes):</em></strong> Time required to clean or reset the work center <strong>after</strong> an operation finishes.</li></ul>',4)),a(o,{src:"/images1/manufacturing/work_center_information_section.png",alt:"Work Center Information Section"}),t[3]||(t[3]=n('<h4 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h4><ul><li><strong><em>Description:</em></strong> A free-text field to add notes, safety guidelines, or specific instructions about the work center. Visible to operators and managers.</li></ul><h4 id="specific-capacity" tabindex="-1">Specific Capacity <a class="header-anchor" href="#specific-capacity" aria-label="Permalink to &quot;Specific Capacity&quot;">​</a></h4><p>Used when the work center handles <strong>different products at different capacities</strong>. For example, an oven might bake 24 small pizzas but only 12 large pizzas per cycle.</p><p>Click <strong>Add a line</strong> and provide:</p><ul><li><strong><em>Product:</em></strong> Product whose capacity differs from the default.</li><li><strong><em>UOM:</em></strong> Unit of measure for this product.</li><li><strong><em>Capacity:</em></strong> Number of units processed per cycle for this specific product.</li><li><strong><em>Setup Time:</em></strong> Override setup time for this product (minutes).</li><li><strong><em>Cleanup Time:</em></strong> Override cleanup time for this product (minutes).</li></ul>',6)),a(o,{src:"/images1/manufacturing/work_center_specific_capacity.png",alt:"Work Center Specific Capacity"})]),t[4]||(t[4]=e("li",null,[e("p",null,[e("strong",null,"Action Buttons:")]),e("ul",null,[e("li",null,[e("strong",null,"Create"),r(" – Save and open the work center record.")]),e("li",null,[e("strong",null,"Create & Create Another"),r(" – Save and immediately open another blank form.")]),e("li",null,[e("strong",null,"Cancel"),r(" – Discard the entry and return to the list view.")])])],-1))]),t[10]||(t[10]=e("h2",{id:"work-center-view-page",tabindex:"-1"},[r("Work Center View Page "),e("a",{class:"header-anchor",href:"#work-center-view-page","aria-label":'Permalink to "Work Center View Page"'},"​")],-1)),t[11]||(t[11]=e("p",null,[r("After creation, you are redirected to the "),e("strong",null,"Work Center View Page"),r(", where you can review every detail and manage related operations.")],-1)),e("ul",null,[t[6]||(t[6]=e("li",null,[e("p",null,[e("strong",null,"View:"),r(" See all general information, production parameters, costing data, and the specific capacity table.")])],-1)),t[7]||(t[7]=e("li",null,[e("p",null,[e("strong",null,"Edit:"),r(" Modify any of the saved fields.")])],-1)),e("li",null,[t[5]||(t[5]=e("p",null,[e("strong",null,"Operations:"),r(" Navigate to the "),e("strong",null,"Operations"),r(" sub-tab to view and manage every routing "),e("a",{href:"./operations.html"},"Operation"),r(" assigned to this work center.")],-1)),a(o,{src:"/images1/manufacturing/work_center_operations_tab.png",alt:"Work Center Operations Tab"})]),t[8]||(t[8]=e("li",null,[e("p",null,[e("strong",null,"Delete / Archive:"),r(" Remove or archive the work center. Archived work centers stay in the database but no longer appear in selection lists.")])],-1))]),t[12]||(t[12]=n('<h2 id="list-view-—-filters-actions" tabindex="-1">List View — Filters &amp; Actions <a class="header-anchor" href="#list-view-—-filters-actions" aria-label="Permalink to &quot;List View — Filters &amp; Actions&quot;">​</a></h2><p>The <strong>Work Centers</strong> list view shows every configured work center with the following columns: <strong>Name</strong>, <strong>Code</strong>, <strong>Company</strong>, <strong>Working Hours</strong>, <strong>Working State</strong>, <strong>Capacity</strong>, <strong>Efficiency</strong>, and <strong>Cost per Hour</strong>.</p><p>You can:</p><ul><li><strong>Filter by:</strong> Company or Working State.</li><li><strong>Group by:</strong> Company.</li><li><strong>Bulk Actions:</strong> Archive, restore, or permanently delete selected records.</li></ul>',4)),a(o,{src:"/images1/manufacturing/work_center_list_view.png",alt:"Work Center List View"}),t[13]||(t[13]=n('<h3 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><p>Work Centers define <strong>where</strong>, <strong>how fast</strong>, and <strong>at what cost</strong> your production runs. Configure each station accurately so the system can:</p><ul><li>Schedule <a href="./../operations/work-orders.html">Work Orders</a> realistically.</li><li>Track real vs. expected duration and OEE.</li><li>Compute manufacturing costs.</li><li>Suggest alternatives when a station is overloaded.</li></ul><blockquote><p><strong>Next step:</strong> Once your Work Centers exist, create the <a href="./operations.html">Operations</a> that run on them.</p></blockquote>',4))])}const _=i(u,[["render",g]]);export{w as __pageData,_ as default};
